package vn.covie.checkout.api; import org.springframework.web.bind.annotation.*; import vn.covie.checkout.api.dto.*; import vn.covie.checkout.application.CheckoutPreviewService; @RestController @RequestMapping("/api/v1/checkouts") public class CheckoutController{private final CheckoutPreviewService previews;public CheckoutController(CheckoutPreviewService previews){this.previews=previews;}@PostMapping("/preview")public CheckoutPreviewResponse preview(@RequestBody CheckoutPreviewRequest request){return previews.preview(request);}}
